CREATE UNIQUE INDEX source_artifact_project_identity ON source_artifacts(id,project_id);
CREATE TABLE plan_documents(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,source_artifact_id TEXT NOT NULL UNIQUE,page_count INTEGER NOT NULL CHECK(page_count BETWEEN 1 AND 50),created_at TEXT NOT NULL,UNIQUE(id,source_artifact_id),FOREIGN KEY(source_artifact_id,project_id) REFERENCES source_artifacts(id,project_id));
CREATE TABLE derived_artifacts(id TEXT PRIMARY KEY,source_artifact_id TEXT NOT NULL REFERENCES source_artifacts(id),storage_key TEXT NOT NULL UNIQUE,mime_type TEXT NOT NULL CHECK(mime_type='image/png'),size INTEGER NOT NULL CHECK(size>0),UNIQUE(id,source_artifact_id));
CREATE TABLE plan_pages(id TEXT PRIMARY KEY,document_id TEXT NOT NULL,source_artifact_id TEXT NOT NULL,page_number INTEGER NOT NULL CHECK(page_number>0),pixel_width INTEGER NOT NULL CHECK(pixel_width BETWEEN 1 AND 16000),pixel_height INTEGER NOT NULL CHECK(pixel_height BETWEEN 1 AND 16000),preview_artifact_id TEXT NOT NULL,UNIQUE(document_id,page_number),FOREIGN KEY(document_id,source_artifact_id) REFERENCES plan_documents(id,source_artifact_id),FOREIGN KEY(preview_artifact_id,source_artifact_id) REFERENCES derived_artifacts(id,source_artifact_id));
CREATE TABLE scale_calibrations(id TEXT PRIMARY KEY,page_id TEXT NOT NULL REFERENCES plan_pages(id),a_x REAL NOT NULL,a_y REAL NOT NULL,b_x REAL NOT NULL,b_y REAL NOT NULL,real_distance REAL NOT NULL CHECK(real_distance>0),meters_per_pixel REAL NOT NULL CHECK(meters_per_pixel>0),status TEXT NOT NULL CHECK(status IN ('DETECTED','VERIFIED','CONFLICTING')),created_at TEXT NOT NULL,actor_id TEXT,description TEXT NOT NULL,UNIQUE(id,page_id),CHECK(a_x!=b_x OR a_y!=b_y));
CREATE TABLE source_registrations(id TEXT PRIMARY KEY,page_id TEXT NOT NULL REFERENCES plan_pages(id),calibration_id TEXT NOT NULL,source_x REAL NOT NULL,source_y REAL NOT NULL,world_x REAL NOT NULL,world_y REAL NOT NULL,rotation REAL NOT NULL,created_at TEXT NOT NULL,UNIQUE(id,page_id,calibration_id),UNIQUE(id,page_id),FOREIGN KEY(calibration_id,page_id) REFERENCES scale_calibrations(id,page_id));
CREATE TABLE floor_source_pages(version_id TEXT NOT NULL,floor_id TEXT NOT NULL,page_id TEXT NOT NULL REFERENCES plan_pages(id),registration_id TEXT,PRIMARY KEY(version_id,floor_id,page_id),FOREIGN KEY(version_id,floor_id) REFERENCES floors(version_id,id),FOREIGN KEY(registration_id,page_id) REFERENCES source_registrations(id,page_id));
CREATE TABLE source_claim_links(version_id TEXT NOT NULL,evidence_id TEXT NOT NULL,page_id TEXT NOT NULL,calibration_id TEXT NOT NULL,registration_id TEXT NOT NULL,PRIMARY KEY(version_id,evidence_id),FOREIGN KEY(version_id,evidence_id) REFERENCES evidence(version_id,id),FOREIGN KEY(registration_id,page_id,calibration_id) REFERENCES source_registrations(id,page_id,calibration_id));
CREATE TABLE normalization_runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,artifact_id TEXT NOT NULL,status TEXT NOT NULL,stage TEXT NOT NULL,error TEXT,document_id TEXT REFERENCES plan_documents(id),created_at TEXT NOT NULL,FOREIGN KEY(artifact_id,project_id) REFERENCES source_artifacts(id,project_id));
CREATE TABLE normalization_events(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES normalization_runs(id),stage TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER plan_documents_immutable_update BEFORE UPDATE ON plan_documents BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER plan_documents_immutable_delete BEFORE DELETE ON plan_documents BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER plan_pages_immutable_update BEFORE UPDATE ON plan_pages BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER plan_pages_immutable_delete BEFORE DELETE ON plan_pages BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER derived_artifacts_immutable_update BEFORE UPDATE ON derived_artifacts BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER derived_artifacts_immutable_delete BEFORE DELETE ON derived_artifacts BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER scale_calibrations_immutable_update BEFORE UPDATE ON scale_calibrations BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER scale_calibrations_immutable_delete BEFORE DELETE ON scale_calibrations BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER source_registrations_immutable_update BEFORE UPDATE ON source_registrations BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER source_registrations_immutable_delete BEFORE DELETE ON source_registrations BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER source_claim_links_immutable_update BEFORE UPDATE ON source_claim_links BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
CREATE TRIGGER source_claim_links_immutable_delete BEFORE DELETE ON source_claim_links BEGIN SELECT RAISE(ABORT,'Source resource is immutable'); END;
